truncate-sentence:
class Solution:
    def truncateSentence(self, s: str, k: int) -> str:
        return ' '.join(s.split()[:k])

unique-number-of-occurrences:
class Solution:
    def uniqueOccurrences(self, arr: list[int]) -> bool:
        cnt = {}
        for v in arr:
            cnt[v] = cnt.get(v, 0) + 1
        vals = list(cnt.values())
        return len(vals) == len(set(vals))

water-bottles:
class Solution:
    def numWaterBottles(self, numBottles: int, numExchange: int) -> int:
        total = numBottles
        empty = numBottles
        while empty >= numExchange:
            new = empty // numExchange
            total += new
            empty = empty % numExchange + new
        return total

odd-string-difference:
class Solution:
    def oddString(self, words: list[str]) -> str:
        def sig(w):
            return [ord(w[i + 1]) - ord(w[i]) for i in range(len(w) - 1)]
        s0 = sig(words[0])
        s1 = sig(words[1])
        s2 = sig(words[2])
        if s0 == s1:
            for w in words[2:]:
                if sig(w) != s0:
                    return w
        elif s0 == s2:
            return words[1]
        return words[0]

number-of-even-and-odd-bits:
class Solution:
    def evenOddBit(self, n: int) -> list[int]:
        even = 0
        odd = 0
        i = 0
        while n:
            if n & 1:
                if i % 2 == 0:
                    even += 1
                else:
                    odd += 1
            n >>= 1
            i += 1
        return [even, odd]

positions-of-large-groups:
class Solution:
    def largeGroupPositions(self, s: str) -> list[list[int]]:
        out = []
        i = 0
        while i < len(s):
            j = i
            while j + 1 < len(s) and s[j + 1] == s[i]:
                j += 1
            if j - i + 1 >= 3:
                out.append([i, j])
            i = j + 1
        return out

prime-arrangements:
class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True
        p = 0
        for x in range(1, n + 1):
            if is_prime(x):
                p += 1
        mod = 10 ** 9 + 7
        res = 1
        for x in range(2, p + 1):
            res = res * x % mod
        for x in range(2, n - p + 1):
            res = res * x % mod
        return res

projection-area-of-3d-shapes:
class Solution:
    def projectionArea(self, grid: list[list[int]]) -> int:
        n = len(grid)
        top = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j]:
                    top += 1
        side = 0
        for row in grid:
            side += max(row)
        front = 0
        for j in range(n):
            front += max(grid[i][j] for i in range(n))
        return top + side + front

rank-transform-of-an-array:
class Solution:
    def arrayRankTransform(self, arr: list[int]) -> list[int]:
        rank = {}
        for i, v in enumerate(sorted(set(arr))):
            rank[v] = i + 1
        return [rank[v] for v in arr]
